<script setup lang="ts">
const props=defineProps<{data:Record<string,any>}>(),{t}=useI18n()
const emit=defineEmits<{filter:[key:string,value:string]}>()
const amount=(row:any)=>Number(row.billed_count?row.billed:row.estimate)
const width=(row:any,rows:any[])=>Math.abs(amount(row))/Math.max(1,...rows.map(item=>Math.abs(amount(item))))*100
const select=(dimension:string,row:any)=>{if(row.id!=null&&!['service','charges'].includes(dimension))emit('filter',dimension==='carrier'?'carrier_id':'country',String(row.id))}
</script>
<template><section v-for="(panels,unit) in props.data" :key="unit" class="distribution"><header><h2>{{t('freight-distribution.title')}} · {{unit}}</h2><p>{{t('freight-distribution.hint')}}</p></header><div class="panels"><WCard v-for="(rows,dimension) in panels" :key="dimension"><h3>{{t('freight-distribution.'+dimension)}}</h3><p v-if="dimension==='charges'">{{t('freight-charges.hint')}}</p><WEmptyState v-if="!rows.length" :title="t('w.table.empty')"/><button v-for="row in rows" :key="String(row.id)" type="button" class="bar-row" :disabled="['service','charges'].includes(String(dimension))||row.id==null" @click="select(String(dimension),row)"><span class="bar-heading"><span>{{dimension==='charges'?t('freight-charges.'+row.id):(row.label||t('freight-distribution.unknown'))}}</span><b>{{amount(row).toLocaleString(undefined,{maximumFractionDigits:2})}}</b></span><span class="track"><i :class="{hollow:!row.billed_count,negative:amount(row)<0}" :style="{width:width(row,rows)+'%'}"/></span><small>{{t('freight-distribution.count',{count:row.count})}}<span v-if="row.comparable_count"> · {{t('freight.difference')}} {{Number(row.difference)>0?'+':''}}{{Number(row.difference).toLocaleString()}}</span></small></button></WCard></div></section></template>
<style scoped>header{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px 20px;margin-bottom:12px}h2{font-size:16px;line-height:24px;margin:0}h3{font-size:14px;line-height:20px;margin:0 0 16px;font-weight:600}p,small{font-size:12px;line-height:18px;color:var(--w-text-3);margin:0}.panels{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.panels>.w-card{min-width:0}.bar-row{display:flex;flex-direction:column;gap:5px;width:100%;border:0;background:none;text-align:left;padding:8px 0;font:inherit;color:var(--w-text-1);cursor:pointer}.bar-row:disabled{cursor:default;opacity:1}.bar-heading{display:flex;justify-content:space-between;gap:12px;font-size:13px}.bar-heading>span{overflow-wrap:anywhere;min-width:0}.bar-heading b{font-weight:600;white-space:nowrap}.track{display:block;height:8px;background:var(--w-bg);border-radius:2px;overflow:hidden}.track i{display:block;height:8px;background:#7855FE;min-width:0}.track .hollow{border:1px solid #7855FE;background:transparent;box-sizing:border-box}.track .negative{background:#DF7A32}@media(max-width:900px){.panels{grid-template-columns:minmax(0,1fr)}}</style>
